// ─── Common Types ────────────────────────────────────────────

export type Level = 'calm' | 'caution' | 'danger' | 'critical';
export type Speaker = 'caller' | 'user' | 'unknown';
export type SignalId =
  | 'authority_claim'
  | 'digital_arrest'
  | 'accusation'
  | 'urgency_threat'
  | 'secrecy_isolation'
  | 'credential_request'
  | 'transfer_demand'
  | 'remote_access'
  | 'reward_task'
  | 'kyc_expiry'
  | 'courier_customs'
  | 'emergency_relative';

export interface Segment {
  id: string;
  text: string;
  is_final: boolean;
  t_start_ms: number;
  t_end_ms: number;
  lang: string | null;
  speaker: Speaker;
}

export interface SignalHit {
  signal_id: SignalId;
  label_en: string;
  label_hi: string;
  weight: number;
  hard: boolean;
  matched: string;
  segment_id: string;
  span_start: number;
  span_end: number;
  t_ms: number;
  context: 'asserted' | 'warning' | 'negated';
}

export interface Combo {
  id: string;
  bonus: number;
}

export interface Analysis {
  score: number; // 0..100
  level: Level;
  hits: SignalHit[];
  combos: Combo[];
  reason_en: string;
  reason_hi: string;
  next_advice_en: string;
  next_advice_hi: string;
  t_ms: number;
  llm_applied: boolean;
}

export interface LlmAssessment {
  scamProbability: number; // 0..1
  tactics: SignalId[];
  reasonEn: string;
  reasonHi: string;
  isLikelyGenuine: boolean;
}

// ─── WebSocket Client → Server Messages ──────────────────────

export interface ClientStartMessage {
  type: 'start';
  mode: 'live' | 'inject' | 'upload' | 'drill';
  lang: 'hi-IN' | 'en-IN' | 'auto';
  sensitivity: 'standard' | 'high';
  sample_rate: number;
  scenario_id?: string;
  case_id?: string;
  job_id?: string;
  speed?: number; // max 4.0
  noise_wer?: number; // inject only
  fixture_id?: string; // mock live replay
}

export interface ClientTextMessage {
  type: 'text';
  id: string;
  text: string;
  is_final: boolean;
  t_ms: number;
}

export interface ClientMuteMessage {
  type: 'mute';
  ms: number;
}

export interface ClientChipMessage {
  type: 'chip';
  act: 'comply' | 'question' | 'verify' | 'refuse';
}

export interface ClientStopMessage {
  type: 'stop';
}

export type ClientMessage =
  | ClientStartMessage
  | ClientTextMessage
  | ClientMuteMessage
  | ClientChipMessage
  | ClientStopMessage;

// ─── WebSocket Server → Client Messages ──────────────────────

export interface ReadyEvent {
  type: 'ready';
  providers: Record<string, unknown>;
}

export interface PartialTextEvent {
  type: 'partial';
  id: string;
  text: string;
  t_ms: number;
}

export interface FinalTextEvent {
  type: 'final';
  id: string;
  text: string;
  t_start_ms: number;
  t_end_ms: number;
  lang: string | null;
}

export interface AnalysisEvent {
  type: 'analysis';
  analysis: Analysis;
}

export interface AlertEvent {
  type: 'alert';
  level: Level;
  text_en: string;
  text_hi: string;
  cooldown_ms: number;
}

export interface CallerEvent {
  type: 'caller';
  node_id: string;
  text: string;
  tactics: SignalId[];
  audio_url: string | null;
  pressure: number; // 0..5
}

export interface DrillEndEvent {
  type: 'ended';
  outcome: 'safe' | 'unsafe';
  scorecard: DrillScorecard;
  debrief: DrillDebrief;
}

export interface DrillScorecard {
  total: number;
  items: Array<{ label: string; points: number }>;
  outcome: 'safe' | 'unsafe';
}

export interface DrillDebrief {
  whatHappened: string;
  turnByTurn: Array<{
    turn: number;
    callerLine: string;
    tactic: string;
    userAction: string;
    result: string;
  }>;
  whatYouDidWell: string;
  whatPutYouAtRisk: string;
  oneThingToRemember: string;
}

export interface ProgressEvent {
  type: 'progress';
  pct: number;
}

export interface SummaryEvent {
  type: 'summary';
  durationSecs: number;
  peakLevel: Level;
  peakScore: number;
  timeToCaution: number | null;
  timeToDanger: number | null;
  timeToCritical: number | null;
  finalScore: number;
  expectedTactics: string[];
  detectedTactics: string[];
  missedTactics: string[];
}

export interface ErrorEvent {
  type: 'error';
  code: string;
  message: string;
}

export interface ClosedEvent {
  type: 'closed';
}

export type ServerEvent =
  | ReadyEvent
  | PartialTextEvent
  | FinalTextEvent
  | AnalysisEvent
  | AlertEvent
  | CallerEvent
  | DrillEndEvent
  | ProgressEvent
  | SummaryEvent
  | ErrorEvent
  | ClosedEvent;

